scwin.usrName = function(keyCode) {

	//----W-Craft WebSquare 변환 확인: on_close----//
    if (keyCode == 13) on_close();
    grd_userlist.Redraw = "false";
    var cnt = 0;
    var len = txb_userid.getValue().length;
    var txtVal = txb_userid.getValue().toUpperCase();
    if (txtVal == "") {
        MxDataSet_dep_usr.SortExpr = "+NO";
    } else {
        MxDataSet_dep_usr.SortExpr = "+EMP_NM";
    }
    MxDataSet_dep_usr.Sort();
    for (i = 1; i <= MxDataSet_dep_usr.countrow; i++) {
        var name = MxDataSet_dep_usr.NameValue(i, "EMP_NM").substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }
    grd_userlist.Redraw = "true";
    MxDataSet_dep_usr.Rowposition = cnt + 9;
    MxDataSet_dep_usr.Rowposition = cnt;
};
