scwin.MxDataSet_dep_part_OnFilter = function(row) {
    if (scwin.jheader != "" && scwin.jheader != "0000") {
        if (MxDataSet_dep_part.getCellData(row, "UP_DEP_CD") == scwin.jheader || MxDataSet_dep_part.getCellData(row, "UP_DEP_CD") == "0000") {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
};

	//----W-Craft WebSquare 변환 확인: Filter----//
scwin.MxDataSet_dep_team_OnFilter = function(row) {
    if (scwin.jheader != "" && scwin.jheader != "0000" && (scwin.jpart == "" || scwin.jpart == "0000")) {
        //본부에서 변경한 경우
        var len_jheader = scwin.jheader.substring(0, 1);
        if (MxDataSet_dep_team.getCellData(row, "DEP_CD").substring(0, 1) == len_jheader || MxDataSet_dep_team.getCellData(row, "UP_DEP_CD") == "0000") {
            return true;
        } else {
            return false;
        }
    }
    if (scwin.jheader != "" && scwin.jheader != "0000" && (scwin.jpart != "" || scwin.jpart != "0000")) {
        if (MxDataSet_dep_team.getCellData(row, "UP_DEP_CD") == scwin.jpart || MxDataSet_dep_team.getCellData(row, "UP_DEP_CD") == "0000") {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
};
